def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    out = [[bg] * w for _ in range(h)]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            min_r = min(y for y, x in cells)
            max_r = max(y for y, x in cells)
            min_c = min(x for y, x in cells)
            max_c = max(x for y, x in cells)
            area = (max_r - min_r + 1) * (max_c - min_c + 1)

            if area >= 4 and len(cells) / area >= 0.7:
                for y in range(min_r, max_r + 1):
                    for x in range(min_c, max_c + 1):
                        out[y][x] = color

    return out
